var i=`0355-rote-grutze`;var r=`world-0355`;var n=`DE`;var a=`western-europe`;var s=8;var l=140;var o={en:`Rote Grütze`,ua:`Роте грютце`};var g={en:`Classic red-berry compote set lightly with starch, served with cream in place of custard.`,ua:`Класичний ягідний десерт із легким крохмальним загущенням, поданий із вершками замість ванільного соусу.`};var d=[{en:`Combine the remaining ingredients, cover partly and stew gently for about 13 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 13 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:13,i:[[`redcurrant`,320,`g`],[`raspberry`,250,`g`],[`sour-cherry`,230,`g`],[`white-granulated-sugar`,125,`g`],[`water`,130,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`cornstarch`,42,`g`],[`water`,65,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 120 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 120 хвилин.`,t:[`rapid-chilling`],m:120,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`heavy-cream`,180,`ml`]]}];var m={slug:i,id:r,country:`DE`,region:a,servings:8,minutes:140,title:o,text:g,steps:d};export{n as country,m as default,r as id,l as minutes,a as region,s as servings,i as slug,d as steps,g as text,o as title};